/*
 * Sprite Screen Tests
 * -----------
 * 
 * this is just me figuring out how to use the draw sprite stuff.
 * the screen classes should be able to draw text and sprites on a screen.
 * the action bar should be able to draw text spaced out along the bottom
 * of the screen.
 * 
 * you should be able to declair the screen and pass it the surface.
 * and then add sprites to the screen. if you want to update the text
 * of a sprite the add text sprite returns the sprite.
 * 
 * create a screen from a IMyTextSurface.
 * 
 * 	progScreen = new Screen(Me.GetSurface(0));
 * 
 * 
 * then add sprites to the screen.
 * 
 * 	progScreen.AddTextSprite(ScreenSprite.ScreenSpriteAnchor.TopCenter,new Vector2(0,0),1.5f,Color.White,"White","Header",TextAlignment.CENTER);
 * 
 * 
 * add an action bar to the bottom of the screen.
 * 
 * 	progScreen.AddActionBar(5,"Up Down + - Back");
 * 
 * includes GridInfo for properties menu items. (with "bindable" properties)
 * 
 * This Script's MDK Project Source: https://github.com/sophiathekitty/DrawSpriteTests
 * MDK Docs for drawing sprites: https://github.com/malware-dev/MDK-SE/wiki/Text-Panels-and-Drawing-Sprites
 * 
 * Icon Attribution:
 * https://www.flaticon.com/free-icons/construction-and-tools Construction-and-tools icons created by Smashicons - Flaticon
 * https://www.flaticon.com/free-icons/area Area icons created by Smashicons - Flaticon
 * https://www.flaticon.com/free-icons/hphp Hp icons created by Smashicons - Flaticon
 */

Screen progScreen;
ScreenMenu menu;
ScreenActionBar actionBar;
PixelIcon pixelDrills;
PixelIcon pixelArea;
PixelIcon heart;
public Program()
{
    // setup GridInfo
    GridInfo.Init("Draw Sprite Tests",GridTerminalSystem,IGC,Me,Echo);
    if(Storage != "") GridInfo.Load(Storage);
    //
    // setup screen
    //
    progScreen = new Screen(Me.GetSurface(0));
    //progScreen.AddTextSprite(ScreenSprite.ScreenSpriteAnchor.TopCenter,new Vector2(0,0),1.5f,Color.White,"White","Header",TextAlignment.CENTER);
    // add action bar
    actionBar = progScreen.AddActionBar(5,"Area Drills Options  Return");
    // add menu
    menu = new ScreenMenu("Mining System",200f,actionBar);
    //menu.AddLabel("test label");
    // offset
    menu.AddVariable("Forward","ForwardOffset","100");
    menu.AddVariable("Horizontal","HorizontalOffset","0");
    menu.AddVariable("Vertical","VerticalOffset","0");

    menu.AddVariable("Show Area", "ShowArea","false");
    menu.AddVariable("Drills On", "DrillsOn","false");
    menu.AddVariable("Drills Count", "DrillsCount","9");
    menu.Visible = false;
    progScreen.AddMenu(menu);
    // add toggle icon for drills
    //progScreen.AddToggleIcon("Textures\\FactionLogo\\Empty.dds", "Textures\\FactionLogo\\Miners\\MinerIcon_3.dds", "DrillsOn",new Vector2(0,25),new Vector2(50,50),ScreenSprite.ScreenSpriteAnchor.CenterRight,TextAlignment.RIGHT);
    // add toggle icon for area
    //progScreen.AddToggleIcon("Textures\\FactionLogo\\Empty.dds", "Textures\\FactionLogo\\Builders\\BuilderIcon_1.dds", "ShowArea",new Vector2(0,-25),new Vector2(50,50),ScreenSprite.ScreenSpriteAnchor.CenterRight,TextAlignment.RIGHT);
    // add pixel icon
    pixelDrills = progScreen.AddTogglePixelIcon(new Vector2(-10,0),"",drillIcon,"DrillsOn",Color.White,new Vector2(64,64),0.02f,ScreenSprite.ScreenSpriteAnchor.CenterRight,TextAlignment.RIGHT);
    pixelArea = progScreen.AddTogglePixelIcon(new Vector2(-10,-50),"",areaIcon,"ShowArea",Color.White,new Vector2(64,64),0.02f,ScreenSprite.ScreenSpriteAnchor.CenterRight,TextAlignment.RIGHT);
    heart = progScreen.AddVariablePixelIcon(new Vector2(-10,10),testIcons,"DrillsCount",Color.White,new Vector2(64,64),0.02f,ScreenSprite.ScreenSpriteAnchor.TopRight,TextAlignment.RIGHT);
    // add a percentage bar
    progScreen.AddPercentageBar("CargoPercent",new Vector2(-100,15),new Vector2(200,20),Color.White,Color.Green,Color.Red,Color.Black,0.5f,ScreenSprite.ScreenSpriteAnchor.TopCenter);
    /*
            pixelTest.fillRGB(0, 0, 0);
            pixelTest.fillRectRGB(10, 10, 20, 20, 0, 100, 200);
            pixelTest.drawCircleRGB(16, 16, 5, 0, 200, 100);
            pixelTest.fillCircleRGB(16, 16, 4, 100, 200, 40);
            */
    //
    // setup runtime
    Runtime.UpdateFrequency = UpdateFrequency.Update100;
}

public void Save()
{
    // Save GridInfo
    Storage = GridInfo.Save();
}
public void Main(string argument, UpdateType updateSource)
{
    if((updateSource == UpdateType.Update100))
    {
        progScreen.Draw();
    }
    else if(argument != "")
    {
        Me.CustomData = argument;
        string action = menu.HandleInput(argument);
        if(action == "back")
        {
            menu.Visible = false;
            menu.SelectedItem.Editing = false;
            actionBar.SetActions("Area Drills Options  Return");
        }
        else if(action == "options")
        {
            menu.Visible = true;
            actionBar.SetActions(menu.menuScrollActions);
        }
        else if(action == "area")
        {
            bool showArea = !GridInfo.GetVarAs<bool>("ShowArea");
            GridInfo.SetVar("ShowArea",showArea.ToString());
        }
        else if(action == "drills")
        {
            bool drillsOn = !GridInfo.GetVarAs<bool>("DrillsOn");
            GridInfo.SetVar("DrillsOn",drillsOn.ToString());
        }
        progScreen.Draw();
    }
}
